import { NextResponse } from 'next/server';
import type { NextRequest } from 'next/server';

// Middleware can't access localStorage (it runs on the edge/server).
// Session validation happens client-side in each protected page.
// This middleware only handles basic routing — no server-side session needed
// since there's no sensitive data rendered server-side in this app.
export function middleware(_req: NextRequest) {
  return NextResponse.next();
}

export const config = {
  matcher: ['/dashboard/:path*', '/setup/:path*'],
};
